		dialer := msdsn.ProtocolDialers[protocol]
		if dialer.CallBrowser(p) {
			if instances == nil {
				d := c.getDialer(p)
				instances, err = getInstances(ctx, d, p.Host)
				if err != nil && logger != nil && uint64(p.LogFlags)&logErrors != 0 {
